entries[173308] = { ["name"] = "Mark of Boistrous Duty", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Strength of the Warden.\nMajor Power:\nVigilant Protector\nInstant 2 min cooldown Taunt all nearby enemies, forcing them to attack you for 6 sec .\nMinor Power:\nEndurance\nEvery 2 sec, store 188 healing, up to a maximum of (Total Health * 0.1). When you dodge or parry an attack, heal for all stored healing.\n\nUnique: Corruption Resistance increased by 10.\n\"One shouldn't shy away from confrontation but embrace it.\"" }
entries[173309] = { ["name"] = "Water Dancer's Technique", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Strength of the Warden.\nMajor Power:\nVigilant Protector\nInstant 2 min cooldown Taunt all nearby enemies, forcing them to attack you for 6 sec, and increase your dodge chance by 15% for 6 sec.\nMinor Power:\nEndurance\nEvery 2 sec, store [ 158 * (1 + Versatility) * (1.25)] healing, up to a maximum of (Total Health * 0.1). When you dodge or parry an attack, heal for all stored healing.\n\nUnique: Corruption Resistance increased by 10.\n\"Swift... and Sudden!\"" }
entries[173310] = { ["name"] = "Manual of Unbalanced Tactics", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Strength of the Warden.\nLearn any Rank 3 essence from Horrific Visions on another character to unlock this essence.\nMajor Power:\nVigilant Protector\nInstant 2 min cooldown Taunt all nearby enemies, forcing them to attack you for 6 sec, and increase your dodge chance by 15% for 6 sec.\n\nTargets affected by your Vigilant Protector take 50% additional damage from you.\nMinor Power:\nEndurance\nEvery 2 sec, store [ 158 * (1 + Versatility) * (1.25)] healing, up to a maximum of (Total Health * 0.1). When you dodge or parry an attack, heal for all stored healing.\n\nThe maximum health of all Tank specialization players in your party or raid is increased by 3%, stacking.\n\nUnique: Corruption Resistance increased by 10." }
entries[173311] = { ["name"] = "Resplendent Warden's Badge", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Strength of the Warden.\nMajor Power:\nVigilant Protector\nInstant 2 min cooldown Taunt all nearby enemies, forcing them to attack you for 6 sec, and increase your dodge chance by 15% for 6 sec.\n\nTargets affected by your Vigilant Protector take 50% additional damage from you.\nMinor Power:\nEndurance\nEvery 2 sec, store [ 158 * (1 + Versatility) * (1.25)] healing, up to a maximum of (Total Health * 0.1). When you dodge or parry an attack, heal for all stored healing.\n\nThe maximum health of all Tank specialization players in your party or raid is increased by 3%, stacking.\n\nUnique: Corruption Resistance increased by 10." }
