entries[173689] = { ["name"] = "Hastily Wrapped Package", ["text"] = "Quest Item\n\"Has a strong scent of Black Briar Rose. It would be ill-advised to hold this too close to your face.\"" }
entries[173690] = { ["name"] = "Cloudstrider Antler", ["text"] = "Quest Item\n\"The perfect toy for a larion to chew on.\"" }
entries[173691] = { ["name"] = "Anima Drainer", ["text"] = "Quest Item\nUse: Drain anima from the target cloudstrider, storing for later use." }
entries[173692] = { ["name"] = "Nemea's Javelin", ["text"] = "Quest Item\nUse: Throw a javelin at a Greatwing, signaling Andira to attack. (10 Sec Cooldown)\n\"Used to work alongside a larion to take down flying prey.\"" }
entries[173693] = { ["name"] = "Jar of Maggots", ["text"] = "Quest Item\nUse: Dump maggots on a dead target, destroying any usable flesh." }
entries[173694] = { ["name"] = "Night Market Template", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Put something evocative here.\"" }
entries[173695] = { ["name"] = "Venthyr Ritual Robes", ["text"] = "Quest Item\nUnique\n\"Ornate, elegant, and beautiful.\"" }
entries[173696] = { ["name"] = "Venthyr Ritual Dagger", ["text"] = "Quest Item\nUnique\n\"Has aided countless souls without ever piercing flesh.\"" }
entries[173697] = { ["name"] = "Venthyr Ritual Tome", ["text"] = "Quest Item\nUnique\n\"Each ritual is endlessly detailed with countless variations.\"" }
entries[173698] = { ["name"] = "Karazhan Scroll", ["text"] = "Quest Item\nUse: Teleports the user to the Blasted Lands." }
entries[173699] = { ["name"] = "Blasted Lands Scroll", ["text"] = "Quest Item\nUse: Teleports the user to the Blasted Lands.\n1 Charge" }
entries[173700] = { ["name"] = "Bonebinder Zal's Key", ["text"] = "Quest Item\nUnique-Equipped" }
entries[173702] = { ["name"] = "Cloudfeather Essence", ["text"] = "Quest Item\n\"Every larion's favorite meal.\"" }
entries[173703] = { ["name"] = "Purity Jug", ["text"] = "Quest Item\nUse: The Monkey King handed this jug to you if any aid was needed in his riddles. Drinking this might help you find where you're going. But why does it smell so strange?\n1 Charge\nSell Price:" }
entries[173704] = { ["name"] = "Granary Jug", ["text"] = "Quest Item\nUse: The Monkey King handed this jug to you if any aid was needed in his riddles. Drinking this might help you find where you're going. It sounds like there might be rice mixed in with the drink.\n1 Charge\nSell Price:" }
entries[173705] = { ["name"] = "The Venthyr Diaries", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A collection of personal log entries from notable venthyr. It is long coveted by those eager to learn about their daily life.\"" }
entries[173706] = { ["name"] = "Jade Jug", ["text"] = "Quest Item\nUse: The Monkey King handed this jug to you if any aid was needed in his riddles. Drinking this might help you find where you're going. How a spectral version of the Monkey King gave this to you is another riddle in itself.\n1 Charge\nSell Price:" }
entries[173707] = { ["name"] = "Soul Hunter's Blade", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The blade from a venthyr rapier. One glance at it reveals the numerous terrors it has wrought.\"" }
entries[173708] = { ["name"] = "Kyrian Shield", ["text"] = "Binds when picked up\nUnique\nUse: Throw it!\n\"A fun way to bond with your larion.\"" }
entries[173709] = { ["name"] = "Vial of Dredger Muck", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Contains muck from a muck pool. Its odor is noxious and singes the tips of your nose hairs.\"" }
entries[173710] = { ["name"] = "Petrified Stonefiend", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A stonefiend completely drained of its anima. In perfect condition too.\"" }
entries[173711] = { ["name"] = "Portrait of The Sire", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A near perfect rendition of Denathrius.\"" }
entries[173712] = { ["name"] = "Ledger of Souls", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A ledger containing the names of thousands of souls sent to Revendreth.\"" }
entries[173713] = { ["name"] = "Vicious White Bonesteed", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"There are few other ways to ride in to battle that feature as many spikes and bones.\"\nVendor:\nDeathguard Netharian\nZone:\nOrgrimmar\nCost:\n1" }
entries[173714] = { ["name"] = "Vicious White Warsaber", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"If you try to give it a belly scratch, you're asking for trouble.\"\nVendor:\nNecrolord Sipe\nZone:\nStormwind City\nCost:\n1" }
entries[173715] = { ["name"] = "Dredger's Toolkit", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A bucket of tools used by the dredgers of Revendreth.\"" }
entries[173716] = { ["name"] = "Mossy Hearthstone", ["text"] = "Quest Item\nUse: Hearths the user to Moonglade.\n1 Charge" }
entries[173717] = { ["name"] = "Perfected Hand Mirror", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"These devices are capable of teleportation in addition to more combative uses. This mirror contains very intricate designs on the casings.\"" }
