entries[173883] = { ["name"] = "Replicating Void Droplets", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Formless Void.\nMajor Power:\nReplica of Knowledge\n40 yd range\n1.5 sec cast Replicate the energy in your target's Heart of Azeroth, gaining access to rank 1 of their currently slotted Major Essence for the next 15 sec. The Formless Void will go on cooldown for 50% longer than the base cooldown of the Essence you replicated.\n\nDoes not work on passive Essences.\nMinor Power:\nSymbiotic Presence\n40 yd range Each time any ally within 40 yds uses an Azerite Essence, gain 22 Primary Stat for 20 sec.\n\nUnique: Corruption Resistance increased by 10.\n\"Insidious, yet extremely powerful.\"" }
entries[173884] = { ["name"] = "Burgeoning Void Droplet", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Formless Void.\nMajor Power:\nReplica of Knowledge\n40 yd range\n1.5 sec cast Replicate the energy in your target's Heart of Azeroth, gaining access to rank 2 of their currently slotted Major Essence for the next 15 sec. The Formless Void will go on cooldown for 40% longer than the base cooldown of the Essence you replicated.\n\nDoes not work on passive Essences.\nMinor Power:\nSymbiotic Presence\nEach time any ally within 40 yds uses an Azerite Essence, gain [source value] Primary Stat for 20 sec.\n\nUnique: Corruption Resistance increased by 10.", ["unresolvedValues"] = true }
entries[173885] = { ["name"] = "Volatile Void Droplet", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Formless Void.\nLearn Rank 3 Formless Void on another character to unlock this essence.\nMajor Power:\nReplica of Knowledge\n40 yd range\n1.5 sec cast Replicate the energy in your target's Heart of Azeroth, gaining access to rank 3 of their currently slotted Major Essence for the next 15 sec. The Formless Void will go on cooldown for 30% longer than the base cooldown of the Essence you replicated.\n\nDoes not work on passive Essences.\nMinor Power:\nSymbiotic Presence\nEach time any ally within 40 yds uses an Azerite Essence, gain [source value] Primary Stat and 18 Haste for 20 sec.\n\nThe ally who used an Azerite Essence also gains 18 Haste for 20 sec. Only one ally can have this Haste effect at a time.\n\nUnique: Corruption Resistance increased by 10.", ["unresolvedValues"] = true }
entries[173886] = { ["name"] = "Bursting Void Droplet", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with The Formless Void.\nMajor Power:\nReplica of Knowledge\n40 yd range\n1.5 sec cast Replicate the energy in your target's Heart of Azeroth, gaining access to rank 3 of their currently slotted Major Essence for the next 15 sec. The Formless Void will go on cooldown for 30% longer than the base cooldown of the Essence you replicated.\n\nDoes not work on passive Essences.\nMinor Power:\nSymbiotic Presence\nEach time any ally within 40 yds uses an Azerite Essence, gain [source value] Primary Stat and 18 Haste for 20 sec.\n\nThe ally who used an Azerite Essence also gains 18 Haste for 20 sec. Only one ally can have this Haste effect at a time.\n\nUnique: Corruption Resistance increased by 10.", ["unresolvedValues"] = true }
entries[173887] = { ["name"] = "Clutch of Ha-Li", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The brood of Ha-Li are comfortable in the blue skies of Pandaria, hunting unsuspecting prey.\"\nDrop:\nHa-Li\nZone:\nVale of Eternal Blossoms" }
