entries[174038] = { ["name"] = "Chime of Celerity", ["text"] = "Binds when picked up\nUnique\nUse: Ring the chime while in Bastion to inspire allies within 10 yards, increasing their movement speed by 554 %. (5 Min Cooldown)\nSell Price:" }
entries[174039] = { ["name"] = "Crate of Cursed Mementos", ["text"] = "Binds when picked up\n<Right Click to Open>\nSell Price:" }
entries[174040] = { ["name"] = "Chains of Regret", ["text"] = "Quest Item\nUse: Hurl the chains at a Rebellious Soul, forcing them to attack you. (5 Sec Cooldown)\n\"Used by the guards of the Catacombs to reign in unruly souls.\"" }
entries[174041] = { ["name"] = "Eyeball Jelly", ["text"] = "Use: Restores ( 10000 * 20 / 5) health over 20 sec.\nMust remain seated while eating.\n\"The texture is surprisingly smooth.\"\nSell Price:" }
entries[174042] = { ["name"] = "Pinch of Faerie Dust", ["text"] = "Binds when picked up\nUnique (10)\nDuration: 15 min (real time)\nUse: Faerie dust makes you lighter, allowing you to fly by double-jumping. Taking any action will cancel this effect.\nLasts 1.5 min." }
entries[174043] = { ["name"] = "Phylactery of Arin'gore", ["text"] = "Quest Item\nUnique\nUse: Shatter Arin'gore's Phylactery and summon the Lich to battle.\n\"The tiny dagger is plainly worked without ornamentation.\"" }
entries[174044] = { ["name"] = "Humming Black Dragonscale", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength or Intellect]\nUse: Call upon Ashjra'kamas, Shroud of Resolve to slow your falling speed for 15 sec. (2 Min Cooldown)\nEquip: Your attacks and abilities have a chance to grant you ephemeral dragon wings, increasing your Haste by 20 and your Speed by 9 for 15 sec.\nSell Price:" }
entries[174045] = { ["name"] = "Orb of Dark Portents", ["text"] = "Binds when picked up\n\"Found in the Horrific Visioons when confronting Thrall or Alleria.\"" }
entries[174046] = { ["name"] = "Orb of Visions", ["text"] = "Binds when picked up\n\"Found in the Horrific Visions when completing the objectives in the initial corrupted areas around Thrall or Alleria.\"" }
entries[174047] = { ["name"] = "Orb of Darkest Visions", ["text"] = "Binds when picked up\n\"Found in the Horrific Visions when completing the objectives in the most corrupted areas.\"" }
entries[174048] = { ["name"] = "Orb of Madness", ["text"] = "Binds when picked up\n\"Found in the Horrific Visions when completing objectives under the effects of Faceless Masks.\"" }
entries[174049] = { ["name"] = "Orb of Darkest Madness", ["text"] = "Binds when picked up\n\"Found in the Horrific Visions when completing objectives under the effects of all Faceless Masks.\"" }
entries[174050] = { ["name"] = "Corrupted Ring - Revel in Violence", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: Your killing blows cause you to revel in violence, rooting you for 6 sec.\nSell Price:" }
entries[174051] = { ["name"] = "Corrupted Ring - Spontaneous Fury", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: Periodically marks a random enemy, making them the target of your fury. While your fury persists, your damage against all other foes is reduced by 10%. (45s cooldown)\nSell Price:" }
entries[174052] = { ["name"] = "Corrupted Ring - Masochistic", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: When you fall below 25% health, taunt all nearby enemies for 5 sec.\nSell Price:" }
entries[174053] = { ["name"] = "Corrupted Ring - Overconfident", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: When you receive overhealing, you refuse the next (Total Health * 25 / 100) Healing within 10 sec.\nSell Price:" }
entries[174054] = { ["name"] = "Corrupted Ring - Last Grasp", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: When you kill an enemy, summon a hostile tentacle at its location which will try to Void Grip you.\nSell Price:" }
entries[174055] = { ["name"] = "Corrupted Ring - Thing From Beyond", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+7 Stamina\n+ 7 Haste\n+ 16 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: The Thing from Beyond will periodically spawn nearby and attack you. Its movement speed increases with Corruption.\nSell Price:" }
entries[174056] = { ["name"] = "Corrupted Ring - Face the Truth", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: An eldritch scroll spawns near you that you and others with this corruption can see. Each second you don't face it, it deals 0 damage to you. If it deals damage to you 5 times, you are feared for 6 sec.\nSell Price:" }
entries[174057] = { ["name"] = "Corrupted Ring - Mesmerizing", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+6 Stamina\n+ 7 Haste\n+ 15 Mastery\nEquip: Your damage and healing are increased by 2%\nEquip: Your damaging spells and abilities against a repeated target reduce your movement speed by 5% for 6 sec, stacking up to 10 times.\nSell Price:" }
