entries[174066] = { ["name"] = "Caravan Hyena", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The canopy atop this dune-wanderer can be stored at your campsite, should you desire to feel the wind in your fur.\"\nAchievement:\nAllied Races: Vulpera" }
entries[174067] = { ["name"] = "Mechagon Mechanostrider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The best mount, logically, serves multiple purposes -- sometimes you need to get places AND reach something high up once you get there.\"\nAchievement:\nAllied Races: Mechagnome" }
