entries[174276] = { ["name"] = "Corrupted Gladiator's Breach", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength or Intellect]\nUse: Harness the corruption of enemy players to open a gateway for 6 sec, allowing bearers of this trinket to slip into the void for up to 6 sec. While in the void, Speed is increased by 40 and you cannot be seen by players outside the void.\n\nLeaving the void increases damage taken by 10% for 6 sec. (2 Min Cooldown)\nSell Price:" }
entries[174277] = { ["name"] = "Lingering Psychic Shell", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+8 [Agility or Strength]\nUse: Reduce the damage you take by 80% for 8 sec until your Psychic Shell has taken 919 total damage. (1 Min Cooldown)\nEquip: While in Ny'alotha and based on your Corruption Resistance, the amount of damage reduction you receive is further reduced by up to 50%.\nSell Price:" }
