entries[174279] = { ["name"] = "Encrypted Ny'alothan Text", ["text"] = "Binds when picked up\nUse: [ Combine 30 Encryted Ny'alothan Texts to create the Burgeoning Void Droplet , which can be used to infuse your Heart of Azeroth with The Formless Void. ][ Combine 15 Encryted Ny'alothan Texts to create the Replicating Void Droplets , which can be used to infuse your Heart of Azeroth with The Formless Void. ]" }
